const posts=[{title:'指尖的慢时光：从一个和弦开始',category:'吉他',desc:'不必急着弹完整首歌。让一个和弦清晰地响起来，也是一件值得开心的事。',icon:'♫',body:['这是一篇用于展示博客排版的示例手记，你可以把它替换成自己的练琴记录。','给自己留十分钟，把手机放远一点，坐下来，听一根弦慢慢响起。练习的开始，可以只是一个熟悉的和弦。','把每根弦逐一拨响，听听有没有闷音。换和弦时不急着追速度，先让手指找到舒服的位置。','下次再来时，可以记下今天练习的和弦、节拍，以及那个突然觉得「好像会了」的瞬间。']},{title:'晚风路过，今天就写到这里',category:'日常',desc:'喜欢夜幕降临时亮起的那盏灯，好像平凡的一天，也有了温柔的落款。',icon:'',body:['这是一篇示例随笔，等待被你的真实故事替换。','夜色落下的时候，街边的小店还亮着灯。把脚步放慢一点，才发现那些白天忽略的细节。','有时候，记录不需要发生什么大事。一阵风、一盏灯、一段恰好听到的旋律，都可以成为今天的注脚。']},{title:'给平凡日子，留一个喜欢的位置',category:'日常',desc:'一小段旋律，一页未写完的手记。收藏这些微不足道，却让人开心的片刻。',icon:'☁',body:['这是一篇展示用的示例手记。','想给喜欢的事情留一个固定的位置。不需要很大，也不必很郑重：书桌的一角，睡前的十分钟，或是博客里的一页。','在这里，可以写练琴的进度，也可以只写「今天听到了一首好听的歌」。每一个小小的记录，都让日子更清晰一点。']}];
let filter='全部';const $=s=>document.querySelector(s);function render(){const q=$('#search').value.trim().toLowerCase();$('#posts').innerHTML='';posts.forEach((p,i)=>{if((filter!=='全部'&&p.category!==filter)||!(p.title+p.desc+p.category).toLowerCase().includes(q))return;const a=document.createElement('article');a.className='post';a.tabIndex=0;a.setAttribute('role','button');a.setAttribute('aria-label','阅读：'+p.title);a.innerHTML=`<div><span class="category">${p.category==='吉他'?'♫ 吉他时光':'☁ 日常碎片'}</span><h3>${p.title}</h3><p>${p.desc}</p><span class="meta">示例手记 &nbsp; / &nbsp; ${p.body.length-1} 段小记</span></div><div class="art" aria-hidden="true">${p.icon}</div>`;a.onclick=()=>openPost(i);a.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openPost(i)}};$('#posts').append(a)});if(!$('#posts').children.length)$('#posts').innerHTML='<p class="empty">还没找到这段回忆，换个关键词试试吧。</p>'}function openPost(i){$('#article-title').textContent=posts[i].title;$('#article-body').replaceChildren(...posts[i].body.map(t=>{const p=document.createElement('p');p.textContent=t;return p}));$('#article').showModal()}$('.dialog-close').onclick=$('.read-done').onclick=()=>$('#article').close();$('#article').onclick=e=>{if(e.target===$('#article')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('#search').oninput=render;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});render()});render();
function readSetting(k){try{return localStorage.getItem(k)}catch{return null}}function saveSetting(k,v){try{localStorage.setItem(k,v)}catch{}}if(readSetting('miette-theme')==='dark')document.body.classList.add('dark');$('#theme').onclick=()=>{document.body.classList.toggle('dark');saveSetting('miette-theme',document.body.classList.contains('dark')?'dark':'light')};
const now=new Date();$('#year').textContent=now.getFullYear();$('#month').textContent=`${now.getFullYear()} 年 ${now.getMonth()+1} 月`;const cal=$('#calendar');['日','一','二','三','四','五','六'].forEach(x=>cal.insertAdjacentHTML('beforeend',`<span class="weekday">${x}</span>`));for(let i=0;i<new Date(now.getFullYear(),now.getMonth(),1).getDay();i++)cal.insertAdjacentHTML('beforeend','<span></span>');for(let i=1;i<=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();i++)cal.insertAdjacentHTML('beforeend',`<span class="${i===now.getDate()?'today':''}">${i}</span>`);
let ctx;[['E',82.41],['A',110],['D',146.83],['G',196],['B',246.94],['e',329.63]].forEach(([name,f])=>{let b=document.createElement('button');b.textContent=name;b.setAttribute('aria-label','拨动 '+name+' 弦');b.onclick=()=>{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.0001,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.22,ctx.currentTime+.015);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+1.7);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+1.8)};$('.strings').append(b)});
const audio=$('#audio'),dock=$('.music-dock');let requested=false;let attempt=0;const formatTime=t=>Number.isFinite(t)?`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`:'0:00';
const savedVolume=Number(readSetting('miette-volume')??.4);audio.volume=Number.isFinite(savedVolume)?Math.max(0,Math.min(1,savedVolume)):.4;
function syncVolume(){$('#volume').value=audio.volume;$('#volume-value').textContent=`${Math.round(audio.volume*100)}%`;$('#mute').textContent=audio.muted?'⊘':'♫';$('#mute').setAttribute('aria-label',audio.muted?'取消静音':'静音');$('#mute').setAttribute('aria-pressed',String(audio.muted))}syncVolume();
function syncPlayback(){const playing=!audio.paused&&!audio.ended;dock.classList.toggle('playing',playing);$('#play').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'暂停富士山下':'播放富士山下')}
async function startMusic(){requested=true;const current=++attempt;$('#music-status').textContent='正在加载音乐…';try{await audio.play();if(current!==attempt)return;saveSetting('miette-music-v2','on')}catch(e){if(current!==attempt)return;requested=false;$('#music-status').textContent=e.name==='NotAllowedError'?'轻点播放，让音乐响起':e.name==='AbortError'?'已暂停':'暂时无法播放，请点击重试';syncPlayback()}}
function pauseMusic(){requested=false;attempt++;audio.pause();saveSetting('miette-music-v2','off');$('#music-status').textContent='已暂停 · 随时继续';syncPlayback()}
$('#play').onclick=()=>{if(requested||!audio.paused)pauseMusic();else startMusic()};audio.onplaying=()=>{requested=false;$('#music-status').textContent='正在播放 · 陪你慢慢读';syncPlayback()};audio.onpause=syncPlayback;audio.onwaiting=()=>{if(!audio.paused)$('#music-status').textContent='缓冲中…'};audio.onerror=()=>{requested=false;$('#music-status').textContent='音频加载失败，请点击重试';syncPlayback()};audio.onended=()=>{$('#music-status').textContent='播放结束 · 再听一次';syncPlayback()};
function syncTime(){const duration=audio.duration;$('#elapsed').textContent=formatTime(audio.currentTime);if(Number.isFinite(duration)&&duration>0){$('#duration').textContent=formatTime(duration);$('#seek').disabled=false;$('#seek').max=duration;$('#seek').value=audio.currentTime;$('#seek').setAttribute('aria-valuetext',`${formatTime(audio.currentTime)} / ${formatTime(duration)}`);$('#seek').style.setProperty('--progress',`${audio.currentTime/duration*100}%`)}}audio.onloadedmetadata=audio.ondurationchange=audio.ontimeupdate=syncTime;$('#seek').oninput=e=>{if(Number.isFinite(audio.duration)){audio.currentTime=Number(e.target.value);syncTime()}};
$('#volume').oninput=e=>{audio.volume=Number(e.target.value);audio.muted=false;saveSetting('miette-volume',audio.volume);syncVolume()};$('#mute').onclick=()=>{audio.muted=!audio.muted;syncVolume()};$('#repeat').onclick=()=>{audio.loop=!audio.loop;$('#repeat').setAttribute('aria-pressed',String(audio.loop));$('#repeat').setAttribute('aria-label',audio.loop?'关闭单曲循环':'开启单曲循环')};
$('#close-music').onclick=()=>{pauseMusic();dock.hidden=true;$('#restore-music').hidden=false;$('#restore-music').focus()};$('#restore-music').onclick=()=>{dock.hidden=false;$('#restore-music').hidden=true;$('#play').focus()};if(readSetting('miette-music-v2')!=='off')startMusic();else $('#music-status').textContent='已暂停 · 点击播放';
